    private fun cleanText(text: String): String {
        return text.replace(Regex("(?i)§[0-9a-fk-orlnmxz]"), "").trim()
    }

    private fun applyGhastGlow(entity: Entity) {
        val id = entity.id
        ghastGlowIds.add(id)
        seenGhastGlowIds.add(id)
        if (!entity.isCurrentlyGlowing) {
            entity.setGlowingTag(true)
        }
    }

    private fun cleanupGhastGlow(level: net.minecraft.client.multiplayer.ClientLevel) {
        if (ghastGlowIds.isEmpty()) return
        val iter = ghastGlowIds.iterator()
        while (iter.hasNext()) {
            val id = iter.next()
            if (seenGhastGlowIds.contains(id)) continue
            val entity = level.getEntity(id)
            if (entity != null) {
                entity.setGlowingTag(false)
            }
            iter.remove()
        }
    }
}

