package set.starlev.features.combat.dungeons.solvers

import net.minecraft.client.Minecraft
import net.minecraft.core.BlockPos
import net.minecraft.world.level.block.Blocks
import net.minecraft.world.phys.AABB
import set.starlev.StarredHeltix
import set.starlev.render.RenderEvents
import set.starlev.utils.detectors.DungeonDetector

/**
 * Подсветка сундука Трёх незнакомцев.
 * После решения пазла находит НПС по нику (name tag) и подсвечивает ближайший к нему сундук.
 */
object ThreeWeirdosChest {
    private val mc = Minecraft.getInstance()
    private var lastChestPos: BlockPos? = null
    private var lastRenderTick = 0L

    fun init() {
        RenderEvents.register { context ->
            if (!StarredHeltix.feature.dungeons.solvers.threeWeirdos) {
                lastChestPos = null
                return@register
            }
            if (!DungeonDetector.isInDungeon()) {
                lastChestPos = null
                return@register
            }

            val correctName = ThreeWeirdos.getCorrectStranger()
            if (correctName == null) {
                lastChestPos = null
                return@register
            }

            val level = mc.level ?: return@register
            val player = mc.player ?: return@register

            // Ищем НПС с name tag = правильный незнакомец
            var npcPos: BlockPos? = null
            for (entity in level.entitiesForRendering()) {
                if (entity !is net.minecraft.world.entity.LivingEntity) continue
                val nameTag = entity.customName?.string?.replace(Regex("(?i)§[0-9a-fk-orlnmxz]"), "")?.trim() ?: continue
                if (nameTag.equals(correctName, ignoreCase = true)) {
                    npcPos = entity.blockPosition()
                    break
                }
            }

            if (npcPos == null) {
                lastChestPos = null
                return@register
            }

            // Ищем ближайший сундук к НПС в радиусе 5 блоков
            var nearestChest: BlockPos? = null
            var nearestDist = Double.MAX_VALUE

            val searchRadius = 5
            for (x in npcPos.x - searchRadius..npcPos.x + searchRadius) {
                for (y in npcPos.y - 2..npcPos.y + 2) {
                    for (z in npcPos.z - searchRadius..npcPos.z + searchRadius) {
                        val pos = BlockPos(x, y, z)
                        val state = level.getBlockState(pos)
                        if (state.`is`(Blocks.CHEST) || state.`is`(Blocks.TRAPPED_CHEST)) {
                            val dist = pos.distSqr(npcPos)
                            if (dist < nearestDist) {
                                nearestDist = dist
                                nearestChest = pos
                            }
                        }
                    }
                }
            }

            if (nearestChest == null) {
                lastChestPos = null
                return@register
            }

            lastChestPos = nearestChest

            // Подсветка сундука
            val chestBox = AABB(nearestChest)
            context.renderBox(chestBox, 0f, 1f, 0f, 0.3f, fill = true)
            context.renderBox(chestBox, 0f, 1f, 0f, 1.0f, fill = false)
            context.renderBoxThroughBlocks(chestBox.inflate(0.01), 0f, 1f, 0f, 1.0f, fill = false, thickness = 3f)

            // Текст над сундуком
            context.renderText(
                "§a§lСУНДУК: $correctName",
                nearestChest.x + 0.5,
                nearestChest.y + 1.5,
                nearestChest.z + 0.5,
                scale = 1.2f,
                color = 0xFF00FF00.toInt(),
                seeThrough = true
            )
        }
    }

    fun reset() {
        lastChestPos = null
    }
}

